package dev.maneszn.advent.mesh;

/** Tiles of the 2048x2048 HD cosmetic atlas (generated by tools/gen_atlas.py). */
public enum Tex {
	GOLD,
	ROSE_GOLD,
	SILVER,
	DARK_METAL,
	ICE,
	GLASS,
	SNOW,
	FUR,
	VELVET_RED,
	SATIN_RED,
	SATIN_GREEN,
	SATIN_BLACK,
	CANDY_RED,
	CANDY_GREEN,
	CANDY_GOLD,
	PEPPERMINT,
	PAPER_RED_STARS,
	PAPER_GREEN_DOTS,
	PAPER_WHITE_FLAKES,
	PAPER_GOLD_STRIPES,
	PAPER_NIGHT_STARS,
	PAPER_ROYAL_PLAID,
	PAPER_RED_PLAID,
	PAPER_ICE_FLAKES,
	LEAF,
	BERRY,
	WOOD,
	BARK,
	COAL,
	CARROT,
	SCALES,
	BELLY_GOLD,
	PINE,
	GLOW_WHITE,
	GLOW_GOLD,
	GLOW_ICE,
	GLOW_RED,
	GLOW_GREEN,
	FLAME,
	CANDLE,
	FUR_BROWN,
	CREAM,
	KNIT_RED,
	KNIT_GREEN,
	GEM_BLUE,
	GEM_RED,
	GEM_GREEN,
	ORNAMENT_RED,
	ORNAMENT_GOLD,
	ORNAMENT_SILVER,
	ORNAMENT_GREEN,
	MANNEQUIN,
	SNOW_GROUND,
	RUNE_GOLD,
	RUNE_ICE,
	SPARKLE,
	FEATHER_GOLD,
	MEMBRANE_RED,
	ANTLER,
	BEAM,
	STAR_GOLD,
	WHITE,
	BLACK,
	HOLLY_DARK;

	public static final int GRID = 8;
	private static final float INSET = 2f / 2048f;

	public float u(float local) { int i = ordinal() % GRID; return (i + INSET * GRID + clamp(local) * (1 - 2 * INSET * GRID)) / GRID; }
	public float v(float local) { int j = ordinal() / GRID; return (j + INSET * GRID + clamp(local) * (1 - 2 * INSET * GRID)) / GRID; }
	private static float clamp(float x) { return x < 0f || x > 1f ? x - (float) Math.floor(x) : x; }
}
